async function go(q){const from=bot.entity.position.floored(),m=new Movements(bot);m.canDig=false;m.canOpenDoors=false;m.allowSprinting=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];const allowed=new Set([from,q].map(p=>p.toString())),old=m.getNeighbors.bind(m);m.getNeighbors=n=>old(n).filter(a=>allowed.has(new Vec3(a.x,a.y,a.z).toString()));bot.pathfinder.setMovements(m);let timer;try{await Promise.race([bot.pathfinder.goto(new goals.GoalBlock(q.x,q.y,q.z)),new Promise((_,r)=>timer=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('GO_BOUND'))},4000))])}finally{clearTimeout(timer);bot.pathfinder.setGoal(null);bot.clearControlStates()}await tick(3);if(!bot.entity.position.floored().equals(q)||!bot.entity.onGround)throw Error('GO_ACTUAL '+bot.entity.position)}
async function step(q){life();const p=bot.entity.position.floored();if(q.y!==p.y||Math.abs(q.x-p.x)+Math.abs(q.z-p.z)!==1)throw Error('EDGE_KIND');if(q.x===7&&q.z===83||q.x===6&&q.z===85)throw Error('RESERVED_PEER_COLUMN');const pre=audit([q,q.offset(0,1,0)]);if(!pre.ok)throw Error('HULL_PRE '+JSON.stringify(pre));for(const y of[1,0]){const b=bot.blockAt(q.offset(0,y,0));if(['sand','gravel','red_sand'].includes(b.name))throw Error('FALLING_HEAD_OR_FOOT');await cut(q.offset(0,y,0));const a=audit();if(!a.ok)throw Error('CUT_HULL '+JSON.stringify(a))}await go(q);const a=audit();if(!a.ok)throw Error('HULL_POST '+JSON.stringify(a));global.P1Tunnel={...(global.P1Tunnel||{}),feet:q,acceptedAt:Date.now()};console.log('ACCEPTED_TUNNEL',q.toString(),bot.health,a.cells)}
async function finish(){bot.pathfinder.setGoal(null);bot.clearControlStates();bot.removeListener('death',die);bot.removeListener('respawn',die);console.log('TUNNEL_END',JSON.stringify({p:bot.entity.position,hp:bot.health,food:bot.food,lost,hull:audit(),inventory:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed])}));}

const p=new Vec3(3,62,115),cap=p.offset(0,2,0),count=n=>bot.inventory.items().filter(i=>i.name===n).reduce((a,i)=>a+i.count,0);const before=count('spruce_log'),y=64+before,hp0=bot.health;let phase='PRE',issue=null,opened=false;try{if(!p.equals(bot.entity.position.floored())||!audit().ok||before>=3)throw Error('SOURCE_PRE');const threats=Object.values(bot.entities).filter(e=>['zombie','zombie_villager','skeleton','creeper','stray','witch'].includes(e.name)&&e.position.y>=61&&e.position.y<=69&&Math.hypot(e.position.x-3.5,e.position.z-115.5)<(e.name==='creeper'?12:8));if(threats.length)throw Error('SOURCE_NEAR_THREAT '+threats.map(e=>e.name));if(bot.blockAt(new Vec3(3,y,115)).name!=='spruce_log')throw Error('LOG_CHANGED');phase='OPEN';await cut(cap);opened=true;phase='LOG';await bot.unequip('hand');await bot.dig(bot.blockAt(new Vec3(3,y,115)),true,'raycast');for(let k=0;k<40&&count('spruce_log')<before+1;k++)await tick(1);if(count('spruce_log')!==before+1)throw Error('LOG_RECEIPT');if(bot.health<hp0)throw Error('SOURCE_DAMAGE');phase='DONE';}catch(e){issue=e.message;console.log('WOOD_WINDOW_ISSUE',phase,issue)}finally{if(!lost&&p.equals(bot.entity.position.floored())&&!full(bot.blockAt(cap))){const it=bot.inventory.items().find(i=>i.name==='dirt');if(it){await bot.equip(it,'hand');await bot._placeBlockWithOptions(bot.blockAt(cap.offset(1,0,0)),new Vec3(-1,0,0),{forceLook:true});await tick(4)}}console.log('WOOD_WINDOW_ACTUAL',JSON.stringify({phase,issue,y,before,after:count('spruce_log'),hp0,hp:bot.health,cap:bot.blockAt(cap).name,opened}));bot.chat('P1 WOOD_WINDOW_ACTUAL before'+before+'→'+count('spruce_log')+' HP'+hp0+'→'+bot.health+' cap'+bot.blockAt(cap).name+' hull'+audit().ok+' issue'+issue+' protectedsourceonly no fieldexit.');await finish();}
